/* Banco de questões autorais (estilo certo/errado da Cebraspe). Não são questões de prova nem de cursinho.
   Campos: id, m (nome da matéria, igual ao do edital), a (começo do título do assunto), e (enunciado), g (true = Certo), c (comentário), f (fonte exata).
   "rev" só recebe uma data quando uma pessoa conferiu a questão com o texto da lei; sem ela, o app mostra "confira a fonte". */
window.BANCO = {versao:1, atualizado:'2026-11-21', qs:[
/* ---------- Direito Penal ---------- */
{id:'pen-01',m:'Noções de Direito Penal',a:'Princípios básicos',e:'Não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal.',g:true,c:'É o princípio da legalidade (anterioridade da lei penal).',f:'CP, art. 1º; CF, art. 5º, XXXIX'},
{id:'pen-02',m:'Noções de Direito Penal',a:'Princípios básicos',e:'A lei posterior que de qualquer modo favoreça o agente aplica-se aos fatos anteriores, mas não alcança os já decididos por sentença condenatória transitada em julgado.',g:false,c:'Alcança, sim: a lei mais benéfica retroage mesmo depois do trânsito em julgado.',f:'CP, art. 2º, parágrafo único'},
{id:'pen-03',m:'Noções de Direito Penal',a:'Princípios básicos',e:'Considera-se praticado o crime no momento da ação ou da omissão, ainda que outro seja o momento do resultado.',g:true,c:'Adota-se a teoria da atividade para o tempo do crime.',f:'CP, art. 4º'},
{id:'pen-04',m:'Noções de Direito Penal',a:'Aplicação da lei penal',e:'Quanto ao lugar do crime, o Código Penal adotou a teoria da ubiquidade: é lugar do crime tanto o da ação ou omissão quanto o do resultado.',g:true,c:'Vale o lugar da conduta, o do resultado, ou onde deveria produzir-se o resultado.',f:'CP, art. 6º'},
{id:'pen-05',m:'Noções de Direito Penal',a:'Aplicação da lei penal',e:'A lei brasileira aplica-se a todo crime cometido no território nacional, sem exceção, mesmo que tratado internacional disponha de modo diferente.',g:false,c:'A regra é aplicada "sem prejuízo de convenções, tratados e regras de direito internacional" (territorialidade temperada).',f:'CP, art. 5º, caput'},
{id:'pen-06',m:'Noções de Direito Penal',a:'Aplicação da lei penal',e:'Para efeitos penais, consideram-se extensão do território nacional as embarcações e aeronaves brasileiras de natureza pública ou a serviço do governo brasileiro, onde quer que se encontrem.',g:true,c:'As privadas só entram quando em alto-mar ou no espaço aéreo correspondente.',f:'CP, art. 5º, § 1º'},
{id:'pen-07',m:'Noções de Direito Penal',a:'Aplicação da lei penal',e:'Ficam sujeitos à lei brasileira, ainda que cometidos no estrangeiro, os crimes contra a vida ou a liberdade do Presidente da República.',g:true,c:'É extraterritorialidade incondicionada.',f:'CP, art. 7º, I, a'},
{id:'pen-08',m:'Noções de Direito Penal',a:'Crime e contravenção',e:'Diz-se o crime tentado quando, iniciada a execução, não se consuma por circunstâncias alheias à vontade do agente.',g:true,c:'Definição legal de tentativa.',f:'CP, art. 14, II'},
{id:'pen-09',m:'Noções de Direito Penal',a:'Crime e contravenção',e:'Salvo disposição em contrário, pune-se a tentativa com a pena do crime consumado, sem diminuição.',g:false,c:'A regra é a pena do consumado diminuída de um a dois terços.',f:'CP, art. 14, parágrafo único'},
{id:'pen-10',m:'Noções de Direito Penal',a:'Crime e contravenção',e:'O agente que, voluntariamente, desiste de prosseguir na execução ou impede que o resultado se produza só responde pelos atos já praticados.',g:true,c:'Desistência voluntária e arrependimento eficaz.',f:'CP, art. 15'},
{id:'pen-11',m:'Noções de Direito Penal',a:'Crime e contravenção',e:'A embriaguez voluntária ou culposa, pelo álcool ou substância de efeitos análogos, exclui a imputabilidade penal.',g:false,c:'Não exclui. Só a embriaguez completa e fortuita (ou proveniente de força maior) isenta de pena.',f:'CP, art. 28, II e § 1º'},
{id:'pen-12',m:'Noções de Direito Penal',a:'Crime e contravenção',e:'Os menores de 18 anos são penalmente inimputáveis, ficando sujeitos às normas da legislação especial.',g:true,c:'Critério biológico, com respaldo constitucional.',f:'CP, art. 27; CF, art. 228'},
{id:'pen-13',m:'Noções de Direito Penal',a:'Crime e contravenção',e:'Quem tem o dever legal de enfrentar o perigo pode alegar estado de necessidade.',g:false,c:'O estado de necessidade não pode ser alegado por quem tinha o dever legal de enfrentar o perigo.',f:'CP, art. 24, § 1º'},
{id:'pen-14',m:'Noções de Direito Penal',a:'Crime e contravenção',e:'Entende-se em legítima defesa quem, usando moderadamente dos meios necessários, repele injusta agressão, atual ou iminente, a direito seu ou de outrem.',g:true,c:'Texto da lei, com os requisitos da legítima defesa.',f:'CP, art. 25'},
{id:'pen-15',m:'Noções de Direito Penal',a:'Crime e contravenção',e:'Nos crimes cometidos sem violência ou grave ameaça, a reparação do dano ou a restituição da coisa, por ato voluntário do agente, até o recebimento da denúncia, reduz a pena de um a dois terços.',g:true,c:'Arrependimento posterior.',f:'CP, art. 16'},
{id:'pen-16',m:'Noções de Direito Penal',a:'Crimes contra a pessoa',e:'A pena do homicídio simples é de reclusão de 12 a 30 anos.',g:false,c:'O homicídio simples é de 6 a 20 anos; 12 a 30 anos é a pena do homicídio qualificado.',f:'CP, art. 121, caput e § 2º'},
{id:'pen-17',m:'Noções de Direito Penal',a:'Crimes contra a pessoa',e:'O crime de lesão corporal consiste em ofender a integridade corporal ou a saúde de outrem.',g:true,c:'Núcleo do tipo do art. 129.',f:'CP, art. 129'},
{id:'pen-18',m:'Noções de Direito Penal',a:'Crimes contra o patrimônio',e:'Configura furto subtrair, para si ou para outrem, coisa alheia móvel.',g:true,c:'Definição do art. 155; sem violência ou grave ameaça.',f:'CP, art. 155'},
{id:'pen-19',m:'Noções de Direito Penal',a:'Crimes contra o patrimônio',e:'O que distingue o roubo do furto é o emprego de arma de fogo.',g:false,c:'O roubo exige violência ou grave ameaça à pessoa, ou redução da possibilidade de resistência; a arma de fogo só majora a pena.',f:'CP, art. 157'},
{id:'pen-20',m:'Noções de Direito Penal',a:'Crimes contra o patrimônio',e:'Se a violência ou a ameaça no roubo é exercida com emprego de arma de fogo, a pena aumenta-se de dois terços.',g:true,c:'Causa de aumento prevista no § 2º-A.',f:'CP, art. 157, § 2º-A, I'},
{id:'pen-21',m:'Noções de Direito Penal',a:'Crimes contra o patrimônio',e:'Está consumado o latrocínio quando o homicídio se consuma, ainda que não se realize o furto ou roubo.',g:true,c:'Súmula 610 do STF.',f:'STF, Súmula 610'},
{id:'pen-22',m:'Noções de Direito Penal',a:'Crimes contra o patrimônio',e:'Se o furto é praticado durante o repouso noturno, a pena é aumentada de um terço.',g:true,c:'Majorante do § 1º.',f:'CP, art. 155, § 1º'},
{id:'pen-23',m:'Noções de Direito Penal',a:'Crimes contra a dignidade sexual',e:'Constranger alguém, mediante violência ou grave ameaça, a ter conjunção carnal ou a praticar outro ato libidinoso configura estupro.',g:true,c:'Redação do art. 213 dada pela Lei 12.015/2009.',f:'CP, art. 213'},
{id:'pen-24',m:'Noções de Direito Penal',a:'Crimes contra a dignidade sexual',e:'O consentimento da vítima menor de 14 anos, a experiência sexual anterior ou a existência de relacionamento amoroso com o agente afastam o crime de estupro de vulnerável.',g:false,c:'São irrelevantes para a caracterização do crime.',f:'CP, art. 217-A; STJ, Súmula 593'},
{id:'pen-25',m:'Noções de Direito Penal',a:'Crimes contra a dignidade sexual',e:'Nos crimes contra a dignidade sexual, procede-se, em regra, mediante ação penal privada.',g:false,c:'Procede-se mediante ação penal pública incondicionada.',f:'CP, art. 225'},
{id:'pen-26',m:'Noções de Direito Penal',a:'Crimes contra a administração pública',e:'Considera-se funcionário público, para efeitos penais, quem exerce cargo, emprego ou função pública, ainda que transitoriamente ou sem remuneração.',g:true,c:'Conceito amplo do art. 327.',f:'CP, art. 327'},
{id:'pen-27',m:'Noções de Direito Penal',a:'Crimes contra a administração pública',e:'No peculato doloso, a reparação do dano antes da sentença irrecorrível extingue a punibilidade.',g:false,c:'A extinção da punibilidade pela reparação antes da sentença irrecorrível vale só para o peculato culposo (§ 3º).',f:'CP, art. 312, §§ 2º e 3º'},
{id:'pen-28',m:'Noções de Direito Penal',a:'Crimes contra a administração pública',e:'Solicitar ou receber, para si ou para outrem, vantagem indevida em razão da função pública configura corrupção passiva.',g:true,c:'Núcleos "solicitar", "receber" e "aceitar promessa".',f:'CP, art. 317'},
{id:'pen-29',m:'Noções de Direito Penal',a:'Crimes contra a administração pública',e:'Na concussão, o funcionário público solicita vantagem indevida em razão da função.',g:false,c:'Na concussão ele exige (há coação); solicitar é núcleo da corrupção passiva.',f:'CP, arts. 316 e 317'},
{id:'pen-30',m:'Noções de Direito Penal',a:'Crimes hediondos',e:'A tortura, o tráfico ilícito de entorpecentes e o terrorismo são crimes equiparados a hediondos.',g:true,c:'Rol da CF e da Lei 8.072.',f:'CF, art. 5º, XLIII; Lei 8.072/1990, art. 2º'},
{id:'pen-31',m:'Noções de Direito Penal',a:'Crimes hediondos',e:'O homicídio simples praticado em atividade típica de grupo de extermínio é hediondo, ainda que cometido por um só agente.',g:true,c:'Está expressamente no rol do art. 1º.',f:'Lei 8.072/1990, art. 1º, I'},
{id:'pen-32',m:'Noções de Direito Penal',a:'Crimes resultantes de preconceito',e:'A prática do racismo constitui crime inafiançável e imprescritível, sujeito à pena de reclusão.',g:true,c:'Previsão constitucional.',f:'CF, art. 5º, XLII'},
{id:'pen-33',m:'Noções de Direito Penal',a:'Crimes de abuso de autoridade',e:'Os crimes de abuso de autoridade exigem finalidade específica de prejudicar outrem ou beneficiar a si ou a terceiro, ou ainda mero capricho ou satisfação pessoal.',g:true,c:'Dolo específico exigido pela lei.',f:'Lei 13.869/2019, art. 1º, § 1º'},
{id:'pen-34',m:'Noções de Direito Penal',a:'Crimes de abuso de autoridade',e:'A perda do cargo, do mandato ou da função pública é efeito automático da condenação por abuso de autoridade.',g:false,c:'Depende de reincidência e deve ser declarada motivadamente na sentença.',f:'Lei 13.869/2019, art. 4º, parágrafo único'},
{id:'pen-35',m:'Noções de Direito Penal',a:'Crimes de abuso de autoridade',e:'A divergência na interpretação da lei ou na avaliação de fatos e provas não configura, por si só, abuso de autoridade.',g:true,c:'Ressalva do § 2º.',f:'Lei 13.869/2019, art. 1º, § 2º'},
{id:'pen-36',m:'Noções de Direito Penal',a:'Crimes de tortura',e:'A condenação por tortura acarreta a perda do cargo, função ou emprego público e a interdição para o exercício pelo dobro do prazo da pena aplicada.',g:true,c:'Efeito da condenação previsto no § 5º.',f:'Lei 9.455/1997, art. 1º, § 5º'},
{id:'pen-37',m:'Noções de Direito Penal',a:'Crimes de tortura',e:'O condenado por tortura, em regra, inicia o cumprimento da pena em regime semiaberto.',g:false,c:'O regime inicial é o fechado (salvo a hipótese de omissão, § 2º).',f:'Lei 9.455/1997, art. 1º, § 7º'},
{id:'pen-38',m:'Noções de Direito Penal',a:'Crimes de tortura',e:'Constitui crime de tortura constranger alguém, com violência ou grave ameaça, causando sofrimento físico ou mental, com o fim de obter informação, declaração ou confissão.',g:true,c:'Hipótese do art. 1º, I, a.',f:'Lei 9.455/1997, art. 1º, I, a'},
{id:'pen-39',m:'Noções de Direito Penal',a:'Estatuto da Criança',e:'Considera-se criança a pessoa até doze anos de idade incompletos e adolescente aquela entre doze e dezoito anos de idade.',g:true,c:'Definição do art. 2º.',f:'ECA, art. 2º'},
{id:'pen-40',m:'Noções de Direito Penal',a:'Estatuto da Criança',e:'A internação do adolescente em estabelecimento educacional não pode exceder cinco anos.',g:false,c:'O limite é de três anos.',f:'ECA, art. 121, § 3º'},
{id:'pen-41',m:'Noções de Direito Penal',a:'Estatuto da Criança',e:'Ao ato infracional praticado por criança correspondem as medidas de proteção.',g:true,c:'Só o adolescente recebe medidas socioeducativas.',f:'ECA, art. 105'},
{id:'pen-42',m:'Noções de Direito Penal',a:'Estatuto da Criança',e:'Nenhum adolescente será privado de sua liberdade senão em flagrante de ato infracional ou por ordem escrita e fundamentada da autoridade judiciária competente.',g:true,c:'Garantia do art. 106.',f:'ECA, art. 106'},
{id:'pen-43',m:'Noções de Direito Penal',a:'Organizações criminosas',e:'Considera-se organização criminosa a associação de quatro ou mais pessoas, estruturalmente ordenada e com divisão de tarefas, ainda que informal, para obter vantagem mediante infrações com penas máximas superiores a quatro anos ou de caráter transnacional.',g:true,c:'Conceito do § 1º do art. 1º.',f:'Lei 12.850/2013, art. 1º, § 1º'},
{id:'pen-44',m:'Noções de Direito Penal',a:'Organizações criminosas',e:'Para configurar organização criminosa bastam três pessoas associadas.',g:false,c:'São necessárias quatro ou mais.',f:'Lei 12.850/2013, art. 1º, § 1º'},
{id:'pen-45',m:'Noções de Direito Penal',a:'Organizações criminosas',e:'Na colaboração premiada, o juiz participa das negociações entre as partes para a formalização do acordo.',g:false,c:'O juiz não participa das negociações; só homologa o acordo.',f:'Lei 12.850/2013, art. 4º, § 6º'},
{id:'pen-46',m:'Noções de Direito Penal',a:'Organizações criminosas',e:'A infiltração de agentes de polícia em tarefas de investigação depende de autorização judicial circunstanciada, motivada e sigilosa, por até seis meses, renováveis.',g:true,c:'Prazo e requisitos do art. 10.',f:'Lei 12.850/2013, art. 10, caput e § 3º'},
{id:'pen-47',m:'Noções de Direito Penal',a:'Crimes de trânsito',e:'Conduzir veículo automotor com capacidade psicomotora alterada em razão da influência de álcool ou de outra substância psicoativa que determine dependência é crime.',g:true,c:'Redação atual do art. 306 do CTB.',f:'Lei 9.503/1997, art. 306'},
{id:'pen-48',m:'Noções de Direito Penal',a:'Crimes de trânsito',e:'O homicídio culposo na direção de veículo automotor é punido com detenção de dois a quatro anos e suspensão ou proibição de dirigir.',g:true,c:'Art. 302 do CTB.',f:'Lei 9.503/1997, art. 302'},
{id:'pen-49',m:'Noções de Direito Penal',a:'Violência doméstica e familiar contra a mulher',e:'Aos crimes praticados com violência doméstica e familiar contra a mulher não se aplica a Lei dos Juizados Especiais Criminais (Lei 9.099/1995).',g:true,c:'Vedação expressa do art. 41.',f:'Lei 11.340/2006, art. 41'},
{id:'pen-50',m:'Noções de Direito Penal',a:'Violência doméstica e familiar contra a mulher',e:'Na lesão corporal praticada no âmbito da violência doméstica contra a mulher, a ação penal depende de representação da vítima.',g:false,c:'A ação penal é pública incondicionada.',f:'STJ, Súmula 542; STF, ADI 4424'},
{id:'pen-51',m:'Noções de Direito Penal',a:'Violência doméstica e familiar contra a mulher',e:'As relações pessoais protegidas pela Lei Maria da Penha dependem da orientação sexual dos envolvidos, só alcançando relações heteroafetivas.',g:false,c:'Independem de orientação sexual.',f:'Lei 11.340/2006, art. 5º, parágrafo único'},
{id:'pen-52',m:'Noções de Direito Penal',a:'Violência doméstica e familiar contra a mulher',e:'Descumprir decisão judicial que defere medida protetiva de urgência prevista na Lei Maria da Penha constitui crime.',g:true,c:'Art. 24-A, incluído pela Lei 13.641/2018.',f:'Lei 11.340/2006, art. 24-A'},
{id:'pen-53',m:'Noções de Direito Penal',a:'Violência doméstica e familiar contra a mulher',e:'São formas de violência doméstica e familiar contra a mulher a física, a psicológica, a sexual, a patrimonial e a moral.',g:true,c:'Rol do art. 7º.',f:'Lei 11.340/2006, art. 7º'},
{id:'pen-54',m:'Noções de Direito Penal',a:'Violência doméstica e familiar contra a mulher',e:'Quando o Município não for sede de comarca, o delegado de polícia pode determinar o afastamento imediato do agressor do lar, comunicando o juiz em 24 horas.',g:true,c:'Previsão do art. 12-C, II.',f:'Lei 11.340/2006, art. 12-C, II e § 1º'},
{id:'pen-55',m:'Noções de Direito Penal',a:'Lei de drogas',e:'Importar, exportar, vender ou guardar drogas sem autorização configura tráfico, com pena de reclusão de cinco a quinze anos e multa.',g:true,c:'Pena-base do art. 33, caput.',f:'Lei 11.343/2006, art. 33'},
{id:'pen-56',m:'Noções de Direito Penal',a:'Lei de drogas',e:'As penas do tráfico são aumentadas de um sexto a dois terços se caracterizado o tráfico entre Estados da Federação ou entre estes e o Distrito Federal.',g:true,c:'Causa de aumento do art. 40, V.',f:'Lei 11.343/2006, art. 40, V'},
{id:'pen-57',m:'Noções de Direito Penal',a:'Estatuto do Desarmamento',e:'Portar arma de fogo de uso permitido, sem autorização, é crime punido com reclusão de dois a quatro anos e multa.',g:true,c:'Art. 14.',f:'Lei 10.826/2003, art. 14'},
{id:'pen-58',m:'Noções de Direito Penal',a:'Estatuto do Desarmamento',e:'Possuir arma de fogo de uso permitido em desacordo com a determinação legal, no interior da residência, é punido com detenção de um a três anos e multa.',g:true,c:'Posse irregular, art. 12.',f:'Lei 10.826/2003, art. 12'},
{id:'pen-59',m:'Noções de Direito Penal',a:'Estatuto do Desarmamento',e:'Portar arma de fogo de uso restrito é punido com reclusão de dois a quatro anos, a mesma pena do porte de arma de uso permitido.',g:false,c:'Uso restrito: reclusão de três a seis anos e multa.',f:'Lei 10.826/2003, art. 16'},
{id:'pen-60',m:'Noções de Direito Penal',a:'Crimes ambientais',e:'As pessoas jurídicas serão responsabilizadas penalmente nos casos previstos na Lei de Crimes Ambientais, sem excluir a responsabilidade das pessoas físicas.',g:true,c:'Art. 3º.',f:'Lei 9.605/1998, art. 3º'},
{id:'pen-61',m:'Noções de Direito Penal',a:'Disposições constitucionais aplicáveis ao direito penal',e:'Nenhuma pena passará da pessoa do condenado, mas a obrigação de reparar o dano pode ser estendida aos sucessores até o limite do patrimônio transferido.',g:true,c:'Princípio da intranscendência.',f:'CF, art. 5º, XLV'},
{id:'pen-62',m:'Noções de Direito Penal',a:'Disposições constitucionais aplicáveis ao direito penal',e:'A Constituição admite penas de caráter perpétuo nos casos de crimes hediondos.',g:false,c:'Não há penas de morte (salvo guerra declarada), caráter perpétuo, trabalhos forçados, banimento nem cruéis.',f:'CF, art. 5º, XLVII'},
{id:'pen-63',m:'Noções de Direito Penal',a:'Disposições constitucionais aplicáveis ao direito penal',e:'Ninguém será considerado culpado até o trânsito em julgado de sentença penal condenatória.',g:true,c:'Presunção de inocência.',f:'CF, art. 5º, LVII'},
/* ---------- Direito Processual Penal ---------- */
{id:'cpp-01',m:'Noções de Direito Processual Penal',a:'Aplicação da lei processual',e:'A lei processual penal aplica-se desde logo, sem prejuízo da validade dos atos realizados sob a vigência da lei anterior.',g:true,c:'Princípio do tempus regit actum.',f:'CPP, art. 2º'},
{id:'cpp-02',m:'Noções de Direito Processual Penal',a:'Inquérito policial',e:'O inquérito policial é dispensável: o Ministério Público pode oferecer denúncia sem ele, se já dispuser de elementos suficientes.',g:true,c:'É peça informativa, não requisito da ação penal.',f:'CPP, arts. 12 e 39, § 5º'},
{id:'cpp-03',m:'Noções de Direito Processual Penal',a:'Inquérito policial',e:'O inquérito policial é um procedimento em que vigoram, como regra, o contraditório e a ampla defesa plenos.',g:false,c:'É inquisitorial; contraditório e ampla defesa plenos não se aplicam, como regra.',f:'CPP, arts. 4º e 9º'},
{id:'cpp-04',m:'Noções de Direito Processual Penal',a:'Inquérito policial',e:'O inquérito deve terminar no prazo de 10 dias se o indiciado estiver preso e de 30 dias se estiver solto.',g:true,c:'Prazo do art. 10 do CPP.',f:'CPP, art. 10'},
{id:'cpp-05',m:'Noções de Direito Processual Penal',a:'Inquérito policial',e:'A autoridade policial pode mandar arquivar os autos de inquérito quando entender não haver crime.',g:false,c:'A autoridade policial não pode arquivar inquérito.',f:'CPP, art. 17'},
{id:'cpp-06',m:'Noções de Direito Processual Penal',a:'Inquérito policial',e:'Nos crimes de ação penal pública incondicionada, o inquérito pode ser instaurado de ofício, por requisição do juiz ou do Ministério Público, ou a requerimento do ofendido.',g:true,c:'Art. 5º, I e II.',f:'CPP, art. 5º, I e II'},
{id:'cpp-07',m:'Noções de Direito Processual Penal',a:'Inquérito policial',e:'Ao tomar conhecimento da infração, a autoridade policial deve providenciar para que não se alterem o estado e a conservação das coisas até a chegada dos peritos.',g:true,c:'Preservação do local do crime.',f:'CPP, art. 6º, I'},
{id:'cpp-08',m:'Noções de Direito Processual Penal',a:'Inquérito policial',e:'O ofendido ou o indiciado podem requerer diligências, que serão realizadas ou não a juízo da autoridade, exceto o exame de corpo de delito.',g:true,c:'Art. 14.',f:'CPP, art. 14'},
{id:'cpp-09',m:'Noções de Direito Processual Penal',a:'Investigação criminal',e:'O indiciamento é ato privativo do delegado de polícia e deve ser fundamentado, mediante análise técnico-jurídica do fato.',g:true,c:'Lei 12.830/2013.',f:'Lei 12.830/2013, art. 2º, § 6º'},
{id:'cpp-10',m:'Noções de Direito Processual Penal',a:'Investigação criminal',e:'As funções de polícia judiciária e a apuração de infrações penais exercidas pelo delegado de polícia têm natureza meramente técnica.',g:false,c:'A lei diz que têm natureza jurídica, essenciais e exclusivas de Estado.',f:'Lei 12.830/2013, art. 2º, caput'},
{id:'cpp-11',m:'Noções de Direito Processual Penal',a:'Investigação criminal',e:'O delegado de polícia somente poderá ser removido por ato fundamentado.',g:true,c:'Garantia funcional do § 5º.',f:'Lei 12.830/2013, art. 2º, § 5º'},
{id:'cpp-12',m:'Noções de Direito Processual Penal',a:'Investigação criminal',e:'Durante a investigação criminal, cabe ao delegado de polícia requisitar perícia, informações, documentos e dados que interessem à apuração dos fatos.',g:true,c:'Art. 2º, § 2º.',f:'Lei 12.830/2013, art. 2º, § 2º'},
{id:'cpp-13',m:'Noções de Direito Processual Penal',a:'Prova',e:'Quando a infração deixar vestígios, o exame de corpo de delito é indispensável, e a confissão do acusado não supre a falta.',g:true,c:'Art. 158.',f:'CPP, art. 158'},
{id:'cpp-14',m:'Noções de Direito Processual Penal',a:'Prova',e:'O juiz não pode fundamentar sua decisão exclusivamente nos elementos informativos colhidos na investigação, ressalvadas as provas cautelares, não repetíveis e antecipadas.',g:true,c:'Art. 155, caput.',f:'CPP, art. 155'},
{id:'cpp-15',m:'Noções de Direito Processual Penal',a:'Prova',e:'São inadmissíveis as provas derivadas das ilícitas em qualquer hipótese, sem exceção.',g:false,c:'Há exceções: ausência de nexo de causalidade e fonte independente.',f:'CPP, art. 157, §§ 1º e 2º'},
{id:'cpp-16',m:'Noções de Direito Processual Penal',a:'Prova',e:'O silêncio do acusado no interrogatório não importa confissão e não pode ser interpretado em prejuízo da defesa.',g:true,c:'Direito ao silêncio.',f:'CPP, art. 186, parágrafo único; CF, art. 5º, LXIII'},
{id:'cpp-17',m:'Noções de Direito Processual Penal',a:'Prova',e:'A confissão do acusado tem valor probatório absoluto e dispensa confronto com as demais provas.',g:false,c:'Seu valor é relativo e deve ser confrontada com as demais provas.',f:'CPP, art. 197'},
{id:'cpp-18',m:'Noções de Direito Processual Penal',a:'Prova',e:'Cadeia de custódia é o conjunto de procedimentos para manter e documentar a história cronológica do vestígio coletado, do reconhecimento até o descarte.',g:true,c:'Definição legal.',f:'CPP, art. 158-A'},
{id:'cpp-19',m:'Noções de Direito Processual Penal',a:'Disposições constitucionais aplicáveis ao direito processual penal',e:'A casa é asilo inviolável, nela se podendo penetrar sem consentimento do morador apenas em flagrante delito, desastre, para prestar socorro ou, durante o dia, por determinação judicial.',g:true,c:'Texto constitucional.',f:'CF, art. 5º, XI'},
{id:'cpp-20',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'Ninguém será preso senão em flagrante delito ou por ordem escrita e fundamentada da autoridade judiciária competente, salvo transgressão militar ou crime propriamente militar.',g:true,c:'Reserva de jurisdição para a prisão.',f:'CF, art. 5º, LXI'},
{id:'cpp-21',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'Considera-se em flagrante delito quem é perseguido, logo após, pela autoridade, pelo ofendido ou por qualquer pessoa, em situação que faça presumir ser autor da infração.',g:true,c:'Flagrante por perseguição (quase flagrante).',f:'CPP, art. 302, III'},
{id:'cpp-22',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'Qualquer do povo poderá e as autoridades policiais e seus agentes deverão prender quem quer que seja encontrado em flagrante delito.',g:true,c:'Flagrante facultativo para o povo e obrigatório para a polícia.',f:'CPP, art. 301'},
{id:'cpp-23',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'Em até 48 horas após a prisão, o auto de prisão em flagrante será encaminhado ao juiz.',g:false,c:'O prazo é de 24 horas.',f:'CPP, art. 306, § 1º'},
{id:'cpp-24',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'Recebido o auto de prisão em flagrante, o juiz deve promover audiência de custódia em até 24 horas, com a presença do preso, de seu advogado ou defensor público e do Ministério Público.',g:true,c:'Art. 310, caput.',f:'CPP, art. 310'},
{id:'cpp-25',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'Na fase de investigação policial, o juiz pode decretar a prisão preventiva de ofício.',g:false,c:'Depende de requerimento do MP, do querelante ou do assistente, ou de representação da autoridade policial.',f:'CPP, art. 311'},
{id:'cpp-26',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'A prisão preventiva pode ser decretada como garantia da ordem pública, da ordem econômica, por conveniência da instrução criminal ou para assegurar a aplicação da lei penal, desde que haja prova da existência do crime, indício suficiente de autoria e perigo gerado pelo estado de liberdade do imputado.',g:true,c:'Fundamentos e pressupostos do art. 312.',f:'CPP, art. 312'},
{id:'cpp-27',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'Em regra, admite-se a prisão preventiva nos crimes dolosos punidos com pena privativa de liberdade máxima superior a quatro anos.',g:true,c:'Art. 313, I.',f:'CPP, art. 313, I'},
{id:'cpp-28',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'Decretada a prisão preventiva, o órgão emissor da decisão deve revisar a necessidade de sua manutenção a cada 90 dias, mediante decisão fundamentada.',g:true,c:'Revisão periódica do art. 316.',f:'CPP, art. 316, parágrafo único'},
{id:'cpp-29',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'O uso de algemas só é lícito em caso de resistência, fundado receio de fuga ou perigo à integridade física própria ou alheia, com justificativa escrita da excepcionalidade.',g:true,c:'Súmula Vinculante 11.',f:'STF, Súmula Vinculante 11'},
{id:'cpp-30',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'A autoridade policial pode conceder fiança nos casos de infração cuja pena privativa de liberdade máxima não seja superior a quatro anos.',g:true,c:'Nos demais, só o juiz, em 48 horas.',f:'CPP, art. 322'},
{id:'cpp-31',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'A autoridade policial pode conceder fiança em qualquer infração, independentemente da pena.',g:false,c:'Só até pena máxima de quatro anos.',f:'CPP, art. 322'},
{id:'cpp-32',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'Não será concedida fiança nos crimes de racismo, tortura, tráfico de drogas, terrorismo, hediondos e nos de ação de grupos armados contra a ordem constitucional.',g:true,c:'Rol do art. 323.',f:'CPP, art. 323'},
{id:'cpp-33',m:'Noções de Direito Processual Penal',a:'Prisão e liberdade',e:'Ninguém será levado à prisão ou nela mantido quando a lei admitir liberdade provisória, com ou sem fiança.',g:true,c:'Garantia constitucional.',f:'CF, art. 5º, LXVI'},
{id:'cpp-34',m:'Noções de Direito Processual Penal',a:'Medidas cautelares',e:'A monitoração eletrônica e a suspensão do exercício de função pública estão entre as medidas cautelares diversas da prisão.',g:true,c:'Rol do art. 319.',f:'CPP, art. 319, VI e IX'},
{id:'cpp-35',m:'Noções de Direito Processual Penal',a:'Medidas cautelares',e:'A fiança e a internação provisória do acusado inimputável ou semi-imputável integram o rol das medidas cautelares diversas da prisão.',g:true,c:'Incisos VII e VIII do art. 319.',f:'CPP, art. 319, VII e VIII'},
{id:'cpp-36',m:'Noções de Direito Processual Penal',a:'Lei nº 7.960',e:'A prisão temporária tem prazo de cinco dias, prorrogável por igual período em caso de extrema e comprovada necessidade.',g:true,c:'Regra geral da Lei 7.960.',f:'Lei 7.960/1989, art. 2º'},
{id:'cpp-37',m:'Noções de Direito Processual Penal',a:'Lei nº 7.960',e:'Nos crimes hediondos e equiparados, a prisão temporária tem prazo de trinta dias, prorrogável por igual período.',g:true,c:'Regra especial da Lei 8.072.',f:'Lei 8.072/1990, art. 2º, § 4º'},
{id:'cpp-38',m:'Noções de Direito Processual Penal',a:'Lei nº 7.960',e:'A prisão temporária pode ser decretada de ofício pelo juiz.',g:false,c:'Só mediante representação da autoridade policial ou requerimento do MP.',f:'Lei 7.960/1989, art. 2º'},
{id:'cpp-39',m:'Noções de Direito Processual Penal',a:'Lei nº 7.960',e:'Decorrido o prazo da prisão temporária, o preso deve ser posto imediatamente em liberdade, salvo se decretada sua prisão preventiva.',g:true,c:'Art. 2º, § 7º.',f:'Lei 7.960/1989, art. 2º, § 7º'},
{id:'cpp-40',m:'Noções de Direito Processual Penal',a:'Juizados especiais criminais',e:'Consideram-se infrações penais de menor potencial ofensivo as contravenções penais e os crimes a que a lei comine pena máxima não superior a dois anos, cumulada ou não com multa.',g:true,c:'Art. 61.',f:'Lei 9.099/1995, art. 61'},
{id:'cpp-41',m:'Noções de Direito Processual Penal',a:'Juizados especiais criminais',e:'A suspensão condicional do processo é cabível nos crimes cuja pena mínima cominada seja igual ou inferior a dois anos.',g:false,c:'O limite da pena mínima é de um ano.',f:'Lei 9.099/1995, art. 89'},
{id:'cpp-42',m:'Noções de Direito Processual Penal',a:'Juizados especiais criminais',e:'Ao autor do fato que, após o termo circunstanciado, for imediatamente encaminhado ao juizado ou assumir o compromisso de a ele comparecer, não se imporá prisão em flagrante.',g:true,c:'Art. 69, parágrafo único.',f:'Lei 9.099/1995, art. 69, parágrafo único'},
{id:'cpp-43',m:'Noções de Direito Processual Penal',a:'Juizados especiais criminais',e:'Nos Juizados Especiais Criminais é admitida a citação por edital, observado o princípio da celeridade.',g:false,c:'Não cabe citação por edital; encontrado o acusado, os autos vão ao juízo comum.',f:'Lei 9.099/1995, art. 66, parágrafo único'},
{id:'cpp-44',m:'Noções de Direito Processual Penal',a:'Juizados especiais criminais',e:'O processo nos Juizados Especiais orienta-se pela oralidade, simplicidade, informalidade, economia processual e celeridade.',g:true,c:'Critérios do art. 62.',f:'Lei 9.099/1995, art. 62'},
{id:'cpp-45',m:'Noções de Direito Processual Penal',a:'Disposições constitucionais aplicáveis ao direito processual penal',e:'O preso será informado de seus direitos, entre os quais o de permanecer calado, sendo-lhe assegurada a assistência da família e de advogado.',g:true,c:'Aviso constitucional.',f:'CF, art. 5º, LXIII'},
{id:'cpp-46',m:'Noções de Direito Processual Penal',a:'Disposições constitucionais aplicáveis ao direito processual penal',e:'A prisão ilegal será imediatamente relaxada pela autoridade judiciária.',g:true,c:'Garantia constitucional.',f:'CF, art. 5º, LXV'},
{id:'cpp-47',m:'Noções de Direito Processual Penal',a:'Disposições constitucionais aplicáveis ao direito processual penal',e:'Não haverá juízo ou tribunal de exceção.',g:true,c:'Princípio do juiz natural.',f:'CF, art. 5º, XXXVII'},
{id:'cpp-48',m:'Noções de Direito Processual Penal',a:'Disposições constitucionais aplicáveis ao direito processual penal',e:'Conceder-se-á habeas corpus sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de locomoção, por ilegalidade ou abuso de poder.',g:true,c:'Art. 5º, LXVIII.',f:'CF, art. 5º, LXVIII'},
{id:'cpp-49',m:'Noções de Direito Processual Penal',a:'Disposições constitucionais aplicáveis ao direito processual penal',e:'Ninguém será preso por ordem verbal, ainda que fundamentada, de autoridade policial.',g:true,c:'Exige-se ordem escrita e fundamentada da autoridade judiciária (ou flagrante).',f:'CF, art. 5º, LXI'},
/* ---------- Direito Constitucional ---------- */
{id:'cf-01',m:'Noções de Direito Constitucional',a:'Aplicabilidade',e:'As normas definidoras dos direitos e garantias fundamentais têm aplicação imediata.',g:true,c:'Regra do § 1º do art. 5º.',f:'CF, art. 5º, § 1º'},
{id:'cf-02',m:'Noções de Direito Constitucional',a:'Aplicabilidade',e:'Os tratados de direitos humanos aprovados em cada Casa do Congresso, em dois turnos, por três quintos dos votos, equivalem às emendas constitucionais.',g:true,c:'Art. 5º, § 3º.',f:'CF, art. 5º, § 3º'},
{id:'cf-03',m:'Noções de Direito Constitucional',a:'Aplicabilidade',e:'A Constituição pode ser emendada durante a vigência de estado de defesa, desde que por três quintos dos membros de cada Casa.',g:false,c:'Não pode ser emendada na vigência de intervenção federal, estado de defesa ou estado de sítio.',f:'CF, art. 60, § 1º'},
{id:'cf-04',m:'Noções de Direito Constitucional',a:'Aplicabilidade',e:'Não será objeto de deliberação a proposta de emenda tendente a abolir a forma federativa de Estado, o voto direto, secreto, universal e periódico, a separação dos Poderes e os direitos e garantias individuais.',g:true,c:'Cláusulas pétreas.',f:'CF, art. 60, § 4º'},
{id:'cf-05',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'Os direitos e garantias fundamentais aplicam-se aos brasileiros e aos estrangeiros residentes no País.',g:true,c:'Art. 5º, caput.',f:'CF, art. 5º, caput'},
{id:'cf-06',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'Ninguém será obrigado a fazer ou deixar de fazer alguma coisa senão em virtude de lei.',g:true,c:'Princípio da legalidade.',f:'CF, art. 5º, II'},
{id:'cf-07',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'É livre a manifestação do pensamento, sendo permitido o anonimato quando houver risco de retaliação.',g:false,c:'O anonimato é vedado.',f:'CF, art. 5º, IV'},
{id:'cf-08',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'Todos podem reunir-se pacificamente, sem armas, em locais abertos ao público, independentemente de autorização, exigido apenas prévio aviso à autoridade competente.',g:true,c:'Art. 5º, XVI.',f:'CF, art. 5º, XVI'},
{id:'cf-09',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'É plena a liberdade de associação para fins lícitos, vedada a de caráter paramilitar.',g:true,c:'Art. 5º, XVII.',f:'CF, art. 5º, XVII'},
{id:'cf-10',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'A lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito.',g:true,c:'Inafastabilidade da jurisdição.',f:'CF, art. 5º, XXXV'},
{id:'cf-11',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'A lei nova pode prejudicar o direito adquirido, o ato jurídico perfeito e a coisa julgada quando houver interesse público.',g:false,c:'A lei não prejudicará esses institutos.',f:'CF, art. 5º, XXXVI'},
{id:'cf-12',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'Qualquer cidadão é parte legítima para propor ação popular que vise anular ato lesivo ao patrimônio público.',g:true,c:'Art. 5º, LXXIII.',f:'CF, art. 5º, LXXIII'},
{id:'cf-13',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'Conceder-se-á mandado de segurança para proteger direito líquido e certo, não amparado por habeas corpus ou habeas data, quando o responsável pela ilegalidade ou abuso de poder for autoridade pública.',g:true,c:'Art. 5º, LXIX.',f:'CF, art. 5º, LXIX'},
{id:'cf-14',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'São direitos sociais, entre outros, a educação, a saúde, a alimentação, o trabalho, a moradia, o transporte, o lazer e a segurança.',g:true,c:'Rol do art. 6º.',f:'CF, art. 6º'},
{id:'cf-15',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'São brasileiros natos os nascidos no Brasil, ainda que de pais estrangeiros, desde que estes não estejam a serviço de seu país.',g:true,c:'Critério do solo (jus soli).',f:'CF, art. 12, I, a'},
{id:'cf-16',m:'Noções de Direito Constitucional',a:'Direitos e garantias',e:'O cargo de Ministro do Supremo Tribunal Federal pode ser ocupado por brasileiro naturalizado.',g:false,c:'É privativo de brasileiro nato.',f:'CF, art. 12, § 3º, IV'},
{id:'cf-17',m:'Noções de Direito Constitucional',a:'Organização político-administrativa',e:'A organização político-administrativa da República compreende a União, os Estados, o Distrito Federal e os Municípios, todos autônomos.',g:true,c:'Art. 18, caput.',f:'CF, art. 18'},
{id:'cf-18',m:'Noções de Direito Constitucional',a:'Organização político-administrativa',e:'Compete privativamente à União legislar sobre direito penal e processual.',g:true,c:'Art. 22, I.',f:'CF, art. 22, I'},
{id:'cf-19',m:'Noções de Direito Constitucional',a:'Organização político-administrativa',e:'Compete à União, aos Estados e ao Distrito Federal legislar concorrentemente sobre direito penitenciário.',g:true,c:'Art. 24, I.',f:'CF, art. 24, I'},
{id:'cf-20',m:'Noções de Direito Constitucional',a:'Organização político-administrativa',e:'A incorporação, a subdivisão ou o desmembramento de Estados dependem apenas de lei ordinária do Congresso Nacional.',g:false,c:'Exigem plebiscito da população diretamente interessada e lei complementar.',f:'CF, art. 18, § 3º'},
{id:'cf-21',m:'Noções de Direito Constitucional',a:'Administração pública',e:'A administração pública obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência.',g:true,c:'LIMPE.',f:'CF, art. 37, caput'},
{id:'cf-22',m:'Noções de Direito Constitucional',a:'Administração pública',e:'O prazo de validade do concurso público é de até dois anos, prorrogável uma vez, por igual período.',g:true,c:'Art. 37, III.',f:'CF, art. 37, III'},
{id:'cf-23',m:'Noções de Direito Constitucional',a:'Administração pública',e:'As funções de confiança são exercidas exclusivamente por servidores ocupantes de cargo efetivo, e os cargos em comissão destinam-se apenas às atribuições de direção, chefia e assessoramento.',g:true,c:'Art. 37, V.',f:'CF, art. 37, V'},
{id:'cf-24',m:'Noções de Direito Constitucional',a:'Administração pública',e:'O exercício do direito de greve é vedado aos policiais civis e a todos os servidores públicos que atuem diretamente na área de segurança pública.',g:true,c:'Tese do STF (Tema 541).',f:'STF, ARE 654.432 (Tema 541)'},
{id:'cf-25',m:'Noções de Direito Constitucional',a:'Administração pública',e:'As pessoas jurídicas de direito público e as de direito privado prestadoras de serviço público respondem pelos danos que seus agentes, nessa qualidade, causarem a terceiros, assegurado o direito de regresso contra o responsável nos casos de dolo ou culpa.',g:true,c:'Responsabilidade objetiva do Estado.',f:'CF, art. 37, § 6º'},
{id:'cf-26',m:'Noções de Direito Constitucional',a:'Administração pública',e:'Os atos de improbidade administrativa importarão a suspensão dos direitos políticos, a perda da função pública, a indisponibilidade dos bens e o ressarcimento ao erário, na forma da lei.',g:true,c:'Art. 37, § 4º.',f:'CF, art. 37, § 4º'},
{id:'cf-27',m:'Noções de Direito Constitucional',a:'Administração pública',e:'O servidor público nomeado para cargo de provimento efetivo em virtude de concurso adquire estabilidade após dois anos de efetivo exercício.',g:false,c:'São três anos.',f:'CF, art. 41, caput'},
{id:'cf-28',m:'Noções de Direito Constitucional',a:'Poder Executivo',e:'O mandato do Presidente da República é de quatro anos.',g:true,c:'Art. 82.',f:'CF, art. 82'},
{id:'cf-29',m:'Noções de Direito Constitucional',a:'Poder Legislativo',e:'Cada Estado e o Distrito Federal elegerão três Senadores, com mandato de oito anos.',g:true,c:'Art. 46.',f:'CF, art. 46, §§ 1º e 2º'},
{id:'cf-30',m:'Noções de Direito Constitucional',a:'Poder Legislativo',e:'As comissões parlamentares de inquérito têm poderes de investigação próprios das autoridades judiciais e são criadas mediante requerimento de um terço dos membros da Casa, para apurar fato determinado e por prazo certo.',g:true,c:'Art. 58, § 3º.',f:'CF, art. 58, § 3º'},
{id:'cf-31',m:'Noções de Direito Constitucional',a:'Poder Legislativo',e:'Desde a expedição do diploma, os membros do Congresso Nacional não podem ser presos, salvo em flagrante de crime inafiançável.',g:true,c:'Imunidade formal.',f:'CF, art. 53, § 2º'},
{id:'cf-32',m:'Noções de Direito Constitucional',a:'Poder Judiciário',e:'São garantias dos magistrados a vitaliciedade, a inamovibilidade e a irredutibilidade de subsídio.',g:true,c:'Art. 95.',f:'CF, art. 95'},
{id:'cf-33',m:'Noções de Direito Constitucional',a:'Funções essenciais',e:'São princípios institucionais do Ministério Público a unidade, a indivisibilidade e a independência funcional.',g:true,c:'Art. 127, § 1º.',f:'CF, art. 127, § 1º'},
{id:'cf-34',m:'Noções de Direito Constitucional',a:'Funções essenciais',e:'Compete ao Ministério Público promover, privativamente, a ação penal pública e exercer o controle externo da atividade policial.',g:true,c:'Art. 129, I e VII.',f:'CF, art. 129, I e VII'},
{id:'cf-35',m:'Noções de Direito Constitucional',a:'Funções essenciais',e:'A Defensoria Pública é instituição essencial à função jurisdicional do Estado, incumbida da orientação jurídica e da defesa dos necessitados.',g:true,c:'Art. 134.',f:'CF, art. 134'},
{id:'cf-36',m:'Noções de Direito Constitucional',a:'Defesa do Estado',e:'A segurança pública, dever do Estado, direito e responsabilidade de todos, é exercida para a preservação da ordem pública e da incolumidade das pessoas e do patrimônio.',g:true,c:'Art. 144, caput.',f:'CF, art. 144'},
{id:'cf-37',m:'Noções de Direito Constitucional',a:'Defesa do Estado',e:'Às polícias civis, dirigidas por delegados de polícia de carreira, incumbem, ressalvada a competência da União, as funções de polícia judiciária e a apuração de infrações penais, exceto as militares.',g:true,c:'Art. 144, § 4º.',f:'CF, art. 144, § 4º'},
{id:'cf-38',m:'Noções de Direito Constitucional',a:'Defesa do Estado',e:'Às polícias militares cabem a polícia ostensiva e a preservação da ordem pública; aos corpos de bombeiros militares, além das atribuições definidas em lei, a execução de atividades de defesa civil.',g:true,c:'Art. 144, § 5º.',f:'CF, art. 144, § 5º'},
{id:'cf-39',m:'Noções de Direito Constitucional',a:'Defesa do Estado',e:'As polícias civis, as polícias militares e os corpos de bombeiros militares subordinam-se ao Ministério da Justiça.',g:false,c:'Subordinam-se aos Governadores dos Estados e do Distrito Federal.',f:'CF, art. 144, § 6º'},
{id:'cf-40',m:'Noções de Direito Constitucional',a:'Defesa do Estado',e:'As polícias penais, federal, estaduais e distrital, vinculam-se ao órgão administrador do sistema penal da unidade federativa a que pertencem.',g:true,c:'Incluídas pela EC 104/2019.',f:'CF, art. 144, § 5º-A'},
{id:'cf-41',m:'Noções de Direito Constitucional',a:'Defesa do Estado',e:'O estado de defesa pode ser decretado pelo Presidente da República, ouvidos o Conselho da República e o Conselho de Defesa Nacional, e tem duração máxima de trinta dias, prorrogável uma vez por igual período.',g:true,c:'Art. 136, caput e § 2º.',f:'CF, art. 136'},
{id:'cf-42',m:'Noções de Direito Constitucional',a:'Defesa do Estado',e:'O estado de sítio dispensa autorização do Congresso Nacional, bastando a decisão do Presidente da República.',g:false,c:'O Presidente solicita autorização ao Congresso para decretar o estado de sítio.',f:'CF, art. 137'},
{id:'cf-43',m:'Noções de Direito Constitucional',a:'Defesa do Estado',e:'As Forças Armadas destinam-se à defesa da Pátria, à garantia dos poderes constitucionais e, por iniciativa de qualquer destes, da lei e da ordem.',g:true,c:'Art. 142.',f:'CF, art. 142'},
/* ---------- Direito Administrativo ---------- */
{id:'adm-01',m:'Noções de Direito Administrativo',a:'Ato administrativo',e:'São elementos do ato administrativo a competência, a finalidade, a forma, o motivo e o objeto.',g:true,c:'Cinco elementos (ou requisitos) clássicos.',f:'Lei 4.717/1965, art. 2º'},
{id:'adm-02',m:'Noções de Direito Administrativo',a:'Ato administrativo',e:'A revogação do ato administrativo fundamenta-se em ilegalidade e produz efeitos retroativos.',g:false,c:'A revogação se baseia em conveniência e oportunidade e produz efeitos para frente (ex nunc).',f:'STF, Súmula 473'},
{id:'adm-03',m:'Noções de Direito Administrativo',a:'Ato administrativo',e:'A Administração pode anular seus próprios atos quando eivados de vícios que os tornam ilegais, e revogá-los por motivo de conveniência ou oportunidade, respeitados os direitos adquiridos.',g:true,c:'Súmula 473.',f:'STF, Súmula 473'},
{id:'adm-04',m:'Noções de Direito Administrativo',a:'Ato administrativo',e:'Pela teoria dos motivos determinantes, a validade do ato vincula-se à existência e à veracidade dos motivos indicados como seu fundamento.',g:true,c:'Se o motivo declarado é falso, o ato é inválido.',f:'Doutrina; Lei 9.784/1999, art. 50'},
{id:'adm-05',m:'Noções de Direito Administrativo',a:'Ato administrativo',e:'No ato discricionário, o Poder Judiciário pode substituir o juízo de conveniência e oportunidade do administrador pelo seu próprio.',g:false,c:'O Judiciário controla a legalidade, não o mérito.',f:'Doutrina'},
{id:'adm-06',m:'Noções de Direito Administrativo',a:'Poderes da administração',e:'Constituem abuso de poder o excesso de poder e o desvio de finalidade.',g:true,c:'Espécies de abuso de poder.',f:'Doutrina; Lei 13.869/2019'},
{id:'adm-07',m:'Noções de Direito Administrativo',a:'Poderes da administração',e:'Compete privativamente ao Presidente da República expedir decretos e regulamentos para a fiel execução das leis.',g:true,c:'Poder regulamentar.',f:'CF, art. 84, IV'},
{id:'adm-08',m:'Noções de Direito Administrativo',a:'Poderes da administração',e:'O poder de polícia administrativa limita o exercício de direitos individuais em benefício do interesse público.',g:true,c:'Conceito do art. 78 do CTN.',f:'CTN, art. 78'},
{id:'adm-09',m:'Noções de Direito Administrativo',a:'Regime jurídico',e:'A Administração obedecerá, entre outros, aos princípios da legalidade, finalidade, motivação, razoabilidade, proporcionalidade, moralidade, ampla defesa, contraditório, segurança jurídica, interesse público e eficiência.',g:true,c:'Rol do art. 2º da Lei 9.784.',f:'Lei 9.784/1999, art. 2º'},
{id:'adm-10',m:'Noções de Direito Administrativo',a:'Responsabilidade civil do Estado',e:'Em regra, a responsabilidade civil do Estado por danos causados por seus agentes é objetiva, dispensando a prova de culpa.',g:true,c:'Teoria do risco administrativo.',f:'CF, art. 37, § 6º'},
{id:'adm-11',m:'Noções de Direito Administrativo',a:'Responsabilidade civil do Estado',e:'A culpa exclusiva da vítima não afasta a responsabilidade do Estado, que responde sempre pelos danos causados a terceiros.',g:false,c:'A culpa exclusiva da vítima exclui o nexo causal e, portanto, a responsabilidade.',f:'Teoria do risco administrativo'},
{id:'adm-12',m:'Noções de Direito Administrativo',a:'Serviços públicos',e:'Serviço adequado é o que satisfaz as condições de regularidade, continuidade, eficiência, segurança, atualidade, generalidade, cortesia na prestação e modicidade das tarifas.',g:true,c:'Princípios do serviço público.',f:'Lei 8.987/1995, art. 6º, § 1º'},
{id:'adm-13',m:'Noções de Direito Administrativo',a:'Organização administrativa',e:'A administração indireta compreende as autarquias, as fundações públicas, as empresas públicas e as sociedades de economia mista.',g:true,c:'Decreto-Lei 200/1967.',f:'Decreto-Lei 200/1967, art. 4º, II'},
{id:'adm-14',m:'Noções de Direito Administrativo',a:'Organização administrativa',e:'A sociedade de economia mista é constituída sob a forma de sociedade anônima, com a maioria das ações com direito a voto pertencentes à pessoa política instituidora.',g:true,c:'Característica essencial.',f:'Lei 13.303/2016, art. 4º'},
{id:'adm-15',m:'Noções de Direito Administrativo',a:'Organização administrativa',e:'A desconcentração ocorre quando o Estado transfere a execução de um serviço para outra pessoa jurídica.',g:false,c:'Isso é descentralização; a desconcentração se dá dentro da mesma pessoa jurídica.',f:'Doutrina'},
{id:'adm-16',m:'Noções de Direito Administrativo',a:'Controle da administração',e:'O controle externo, a cargo do Congresso Nacional, será exercido com o auxílio do Tribunal de Contas da União.',g:true,c:'Art. 71.',f:'CF, art. 71'},
{id:'adm-17',m:'Noções de Direito Administrativo',a:'Processo administrativo',e:'O direito da Administração de anular os atos de que decorram efeitos favoráveis aos destinatários decai em cinco anos, contados da prática, salvo comprovada má-fé.',g:true,c:'Art. 54 da Lei 9.784.',f:'Lei 9.784/1999, art. 54'},
{id:'adm-18',m:'Noções de Direito Administrativo',a:'Processo administrativo',e:'Salvo disposição legal específica, o prazo para interposição de recurso administrativo é de trinta dias.',g:false,c:'É de dez dias, contados da ciência ou divulgação oficial da decisão.',f:'Lei 9.784/1999, art. 59'},
{id:'adm-19',m:'Noções de Direito Administrativo',a:'Processo administrativo',e:'Concluída a instrução, a Administração tem o prazo de até trinta dias para decidir, salvo prorrogação por igual período expressamente motivada.',g:true,c:'Art. 49.',f:'Lei 9.784/1999, art. 49'},
{id:'adm-20',m:'Noções de Direito Administrativo',a:'Licitações e contratos',e:'São modalidades de licitação previstas na Lei 14.133/2021: pregão, concorrência, concurso, leilão e diálogo competitivo.',g:true,c:'Art. 28.',f:'Lei 14.133/2021, art. 28'},
{id:'adm-21',m:'Noções de Direito Administrativo',a:'Licitações e contratos',e:'O convite e a tomada de preços continuam sendo modalidades de licitação na Lei 14.133/2021.',g:false,c:'Foram extintas pela nova lei.',f:'Lei 14.133/2021, art. 28'},
{id:'adm-22',m:'Noções de Direito Administrativo',a:'Licitações e contratos',e:'A contratação direta por inexigibilidade é cabível quando houver inviabilidade de competição.',g:true,c:'Art. 74.',f:'Lei 14.133/2021, art. 74'},
{id:'adm-23',m:'Noções de Direito Administrativo',a:'Agente público',e:'Os atos de improbidade administrativa que importam enriquecimento ilícito exigem dolo, não bastando a mera culpa.',g:true,c:'Alteração da Lei 14.230/2021: só ação ou omissão dolosa.',f:'Lei 8.429/1992, art. 1º, § 1º'},
{id:'adm-24',m:'Noções de Direito Administrativo',a:'Agente público',e:'A ação para as sanções por improbidade prescreve em oito anos, contados da ocorrência do fato.',g:true,c:'Prazo da Lei 14.230/2021.',f:'Lei 8.429/1992, art. 23'},
{id:'adm-25',m:'Noções de Direito Administrativo',a:'Cargo, emprego e função',e:'Os cargos em comissão são de livre nomeação e exoneração.',g:true,c:'Art. 37, II.',f:'CF, art. 37, II'}
]};
